import ch.qos.logback.core.Filter;

protected void subAppend(ILoggingEvent event) {
    // Ensure the event is not null
    if (event == null) {
        return;
    }

    // Get the logger
    Logger logger = LoggerFactory.getLogger("org.slf4j.Logger");

    // Create a pattern layout
    PatternLayout patternLayout = new PatternLayout();
    patternLayout.setPattern("%d{yyyy-MM-dd HH:mm:ss} %-5level %logger{36} - %msg%n");

    // Create an encoder and set the pattern layout
    Encoder<ILoggingEvent> encoder = newPatternLayoutEncoder();
    ((PatternLayoutEncoder) encoder).setPatternLayout(patternLayout);

    // Create a file appender and set the encoder and file name
    FileAppender<ILoggingEvent> fileAppender = new FileAppender<>();
    fileAppender.setEncoder(encoder);
    fileAppender.setFile("logs/log.txt");
    fileAppender.start();

    // Add the file appender to the logger
    logger.addAppender(fileAppender);

    // Log the event
    logger.log(event);

    // Close the appender
    fileAppender.stop();
}
