public class TimeBucketCompressor {
    public static long compressTimeBucket(long timeBucket, int dayStep) {
        // Step 1: Extract year, month, and day from the time bucket
        int year = (int) (timeBucket / 1000000);
        int month = (int) ((timeBucket % 1000000) / 10000);
        int day = (int) ((timeBucket % 10000) / 100);

        // Step 2: Determine the day to reformat the time bucket
        int newDay;
        if (day <= dayStep) {
            newDay = 1;
        } else {
            if (day % 7 == 0) {
                newDay = day - 1;
            } else if (day % 7 == 1) {
                newDay = day - dayStep - 1;
            } else {
                newDay = day - dayStep;
            }
        }

        // Step 3: Reformat the time bucket
        long compressedTimeBucket = (long) year * 1000000 + (long) month * 10000 + newDay;

        return compressedTimeBucket;
    }
}
