public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    final int end = index + len;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if ((c >> 7) == 0) {
            size += 1;
        } else if ((c >> 5) == 6) {
            size += 2;
        } else if ((c >> 4) == 14) {
            size += 3;
        } else if ((c >> 3) == 30) {
            size += 4;
        } else {
            throw new IllegalArgumentException("Invalid UTF-16 sequence");
        }
    }
    return size;
}
