import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    Path path = Paths.get(u);
    if (path.isAbsolute()) {
        path = path.subpath(1, path.getNameCount());
    }
    for (Path name : path) {
        if (decode) {
            try {
                name = Paths.get(name.toString("UTF-8"));
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
        pathSegments.add(new PathSegmentImpl(name.toString()));
    }
    return pathSegments;
}

class PathSegmentImpl {
    private String segment;

    public PathSegmentImpl(String segment) {
        this.segment = segment;
    }

    public String getSegment() {
        return segment;
    }
}
