public class GraphUtils {

    private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<E> graph) {
        List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparators = new ArrayList<>();

        for (Edge<E> edge : graph.getEdges()) {
            List<Pair<Integer,Integer>> localSeparators = computeLocalSeparators(graph, edge);
            globalSeparators.add(Pair.with(localSeparators, edge));
        }

        return globalSeparators;
    }

    private List<Pair<Integer,Integer>> computeLocalSeparators(Graph<E> graph, Edge<E> edge) {
        List<Pair<Integer,Integer>> localSeparators = new ArrayList<>();

        for (Integer node : graph.getNeighbors(edge)) {
            localSeparators.add(Pair.with(node, edge.getTarget()));
        }

        return localSeparators;
    }
}
