import java.lang.reflect.TypeVariable;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;

public static Type resolveBound(TypeVariable<?> typeVariable) {
    Type genericDeclaration = typeVariable.getGenericDeclaration();
    if (genericDeclaration instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericDeclaration;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        for (Type type : actualTypeArguments) {
            if (type.equals(typeVariable)) {
                if (parameterizedType.getOwnerType() != null) {
                    Type ownerType = resolveBound(parameterizedType.getOwnerType());
                    if (ownerType instanceof ParameterizedType) {
                        ParameterizedType ownerParameterizedType = (ParameterizedType) ownerType;
                        Type[] ownerActualTypeArguments = ownerParameterizedType.getActualTypeArguments();
                        for (Type ownerTypeArgument : ownerActualTypeArguments) {
                            if (ownerTypeArgument.equals(typeVariable)) {
                                return ownerParameterizedType.getRawType();
                            }
                        }
                    }
                }
                return typeVariable.getBounds()[0];
            }
        }
    }
    return Unknown.class;
}
