private List<String> parseDescriptor(String descriptor) {
    List<String> types = new ArrayList<>();
    for (int i = 0; i < descriptor.length(); i++) {
        char c = descriptor.charAt(i);
        if (c == 'L') {
            int endIndex = descriptor.indexOf(';', i);
            types.add(descriptor.substring(i, endIndex + 1));
            i = endIndex;
        } else if (c == 'I' || c == 'J' || c == 'F' || c == 'D' || c == 'Z' || c == 'C' || c == 'S') {
            types.add(String.valueOf(c));
        } else if (c == '(') {
            int endIndex = descriptor.indexOf(')', i);
            String argDescriptor = descriptor.substring(i + 1, endIndex);
            types.addAll(parseDescriptor("(" + argDescriptor + ")"));
            i = endIndex;
        }
    }
    return types;
}
