public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    ByteBuffer buffer = ByteBuffer.wrap(fileToBytes(file));
    AtomicLong timestamp = new AtomicLong(0);
    while (buffer.hasRemaining()) {
        Timestamp ts = parseTimestamp(buffer);
        timestamp.set(ts.getTimestamp());
        if (timeRanges.stream().anyMatch(range -> range.isInTimeRange(timestamp.get()))) {
            snapshots.add(parseThreadSnapshot(buffer));
        }
    }
    return snapshots;
}

private static byte[] fileToBytes(File file) throws IOException {
    byte[] bytes = new byte[(int) file.length()];
    try (FileInputStream fis = new FileInputStream(file)) {
        fis.read(bytes);
    }
    return bytes;
}

